import fs from'node:fs';

const read=p=>fs.readFileSync(p,'utf8');
const write=(p,s)=>fs.writeFileSync(p,s);
const replace=(src,from,to,label)=>{if(!src.includes(from))throw new Error(`Missing ${label}`);return src.replace(from,to)};

// Chat configuration: 0 means no waiting requirement; 1-900 are valid timed waits.
let runtime=read('assets/js/config-runtime.js');
runtime=replace(runtime,"minimum_seconds:integer(chatRaw.minimum_seconds,45,30,900),","minimum_seconds:integer(chatRaw.minimum_seconds,45,0,900),",'chat runtime minimum');
write('assets/js/config-runtime.js',runtime);

let configuration=read('assets/js/admin/configuration.js');
configuration=replace(configuration,"${input('minimum_seconds','Minimum seconds',c.minimum_seconds,{type:'number',min:30,max:900,required:true})}","${input('minimum_seconds','Minimum seconds',c.minimum_seconds,{type:'number',min:0,max:900,required:true,help:'Set 0 to remove the waiting requirement. Values from 1 to 900 seconds are allowed.'})}",'Admin chat minimum');
write('assets/js/admin/configuration.js',configuration);

let app=read('assets/js/app.js');
app=replace(app,"const RELEASE='20260805-experience-r1';","const RELEASE='20260809-controls-r1';",'release marker');
app=replace(app,"const chatMinimumSeconds=()=>chatConfig().minimum_seconds;\nconst chatRequiredReplies=()=>chatConfig().required_replies;\nconst chatMinimumReplyLength=()=>chatConfig().minimum_reply_length;","const chatMinimumSeconds=()=>Math.max(0,Number(app.chat?.minimumSeconds??chatConfig().minimum_seconds??45));\nconst chatRequiredReplies=()=>Math.max(1,Number(app.chat?.requiredReplies??chatConfig().required_replies??4));\nconst chatMinimumReplyLength=()=>Math.max(1,Number(app.chat?.minimumReplyLength??chatConfig().minimum_reply_length??12));",'attempt-aware chat contract');
app=replace(app,"function clearChat(){clearTimeout(app.chatTimer);app.chatTimer=null;app.chat=null;localStorage.removeItem(chatRecoveryKey())}","function clearChat(){clearInterval(app.chatTimer);app.chatTimer=null;app.chat=null;localStorage.removeItem(chatRecoveryKey())}",'chat cleanup');
app=replace(app,"function resumeChat(open,saved){const meta=partnerByName(open.partner||saved?.partner),same=saved?.attemptId===open.attempt_id;app.chat={partner:meta.name,meta,attemptId:open.attempt_id,startedAt:serverTime(open.started_at),stage:same?Number(saved.stage||0):0,replies:same&&Array.isArray(saved.replies)?saved.replies:[],replyTexts:same&&Array.isArray(saved.replyTexts)?saved.replyTexts:[],promptSet:same&&Number.isInteger(Number(saved.promptSet))?Number(saved.promptSet):choosePromptSet(open.attempt_id)};openChatUi(same?'Your timed guided chat has been restored.':`The timer was restored. Complete ${chatRequiredReplies()} new meaningful replies in this browser.`)}","function resumeChat(open,saved){const meta=partnerByName(open.partner||saved?.partner),same=saved?.attemptId===open.attempt_id;app.chat={partner:meta.name,meta,attemptId:open.attempt_id,startedAt:serverTime(open.started_at),minimumSeconds:Math.max(0,Number(open.minimum_seconds??chatConfig().minimum_seconds??45)),requiredReplies:Math.max(1,Number(open.required_replies??chatConfig().required_replies??4)),minimumReplyLength:Math.max(1,Number(open.minimum_reply_length??chatConfig().minimum_reply_length??12)),stage:same?Number(saved.stage||0):0,replies:same&&Array.isArray(saved.replies)?saved.replies:[],replyTexts:same&&Array.isArray(saved.replyTexts)?saved.replyTexts:[],promptSet:same&&Number.isInteger(Number(saved.promptSet))?Number(saved.promptSet):choosePromptSet(open.attempt_id)};openChatUi(same?'Your guided chat has been restored.':`Your guided chat was restored. Complete ${chatRequiredReplies()} new meaningful replies in this browser.`)}",'resume server contract');
app=replace(app,"function updateChatTimer(){if(!app.chat)return;const total=Math.max(1,Number(chatMinimumSeconds()||45)),required=Math.max(1,Number(chatRequiredReplies()||4)),started=Number(app.chat.startedAt||Date.now()),elapsed=Math.max(0,Math.floor((Date.now()-started)/1000)),remaining=Math.max(0,total-elapsed),fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;const timer=$('#chat-timer'),complete=$('#chat-complete');if(timer){timer.textContent=remaining>0?`${fmt(remaining)} remaining`:'00:00 · Ready';timer.dataset.remaining=String(remaining)}if(app.chat.replies.length===required){$('#chat-ready')?.classList.remove('hidden');if(complete){complete.disabled=remaining>0;complete.textContent=remaining>0?`Ready in ${remaining}s`:chatConfig().completion_wording}}else if(complete){complete.disabled=true}return remaining}","function updateChatTimer(){if(!app.chat)return;const total=chatMinimumSeconds(),required=chatRequiredReplies(),started=Number(app.chat.startedAt||Date.now()),elapsed=Math.max(0,Math.floor((Date.now()-started)/1000)),remaining=Math.max(0,total-elapsed),fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;const timer=$('#chat-timer'),complete=$('#chat-complete');if(timer){timer.textContent=total===0?'No wait · Ready':remaining>0?`${fmt(remaining)} remaining`:'00:00 · Ready';timer.dataset.remaining=String(remaining)}if(app.chat.replies.length===required){$('#chat-ready')?.classList.remove('hidden');if(complete){complete.disabled=remaining>0;complete.textContent=remaining>0?`Ready in ${remaining}s`:chatConfig().completion_wording}}else if(complete){complete.disabled=true}return remaining}",'countdown renderer');
app=replace(app,"async function startChat(partner,button){if(button){button.disabled=true;button.textContent='Opening guided chat…'}try{const attempt=await api.startChat(partner),meta=partnerByName(partner);app.chat={partner,meta,attemptId:attempt.attempt_id,startedAt:serverTime(attempt.started_at),stage:0,replies:[],replyTexts:[],promptSet:choosePromptSet(attempt.attempt_id)};persistChat();openChatUi()}catch(error){alert(error.message||'Guided chat could not start.')}finally{if(button){button.disabled=false;button.textContent='Start guided chat'}}}","async function startChat(partner,button){if(button){button.disabled=true;button.textContent='Opening guided chat…'}try{const attempt=await api.startChat(partner),meta=partnerByName(partner);app.chat={partner,meta,attemptId:attempt.attempt_id,startedAt:serverTime(attempt.started_at),minimumSeconds:Math.max(0,Number(attempt.minimum_seconds??chatConfig().minimum_seconds??45)),requiredReplies:Math.max(1,Number(attempt.required_replies??chatConfig().required_replies??4)),minimumReplyLength:Math.max(1,Number(attempt.minimum_reply_length??chatConfig().minimum_reply_length??12)),stage:0,replies:[],replyTexts:[],promptSet:choosePromptSet(attempt.attempt_id)};persistChat();openChatUi()}catch(error){alert(error.message||'Guided chat could not start.')}finally{if(button){button.disabled=false;button.textContent='Start guided chat'}}}",'start server contract');
app=replace(app,"function startChatCountdown(){clearTimeout(app.chatTimer);const tick=()=>{if(!app.chat){app.chatTimer=null;return}updateChatTimer();app.chatTimer=setTimeout(tick,Math.max(200,1000-Date.now()%1000))};tick()}","function startChatCountdown(){clearInterval(app.chatTimer);app.chatTimer=null;if(!app.chat)return;updateChatTimer();app.chatTimer=setInterval(()=>{if(!app.chat){clearInterval(app.chatTimer);app.chatTimer=null;return}updateChatTimer()},250)}",'countdown scheduler');
app=app.replaceAll('clearTimeout(app.chatTimer);app.chatTimer=null','clearInterval(app.chatTimer);app.chatTimer=null');
app=app.replace("today<limit?`About ${chat.minimum_seconds} seconds · ${reward} after approval`:'Follow a clear guide and submit your activity'","today<limit?`${Number(chat.minimum_seconds||0)>0?`About ${chat.minimum_seconds} seconds`:'No waiting requirement'} · ${reward} after approval`:'Follow a clear guide and submit your activity'");
app=app.replace("${today} of ${limit} approved · ${chat.required_replies} replies · minimum ${chat.minimum_seconds} seconds","${today} of ${limit} approved · ${chat.required_replies} replies · ${Number(chat.minimum_seconds||0)>0?`minimum ${chat.minimum_seconds} seconds`:'no waiting requirement'}");
write('assets/js/app.js',app);

// Admin tasks: current list excludes archived/ended tasks, preserving claim history in the database.
let core=read('assets/js/admin/core.js');
core=replace(core,"async function tasks(){const rows=await api.adminTasks();","async function tasks(){const allRows=await api.adminTasks(),rows=(allRows||[]).filter(r=>r.status!=='ended');",'current task filter');
core=core.replace('<div class="section-title"><h2>Current tasks</h2></div>','<div class="section-title"><div><h2>Current tasks & sponsored ads</h2><small>Removed items disappear here while past claim history stays protected.</small></div></div>');
core=core.replaceAll('>End / Remove</button>','>Remove</button>');
core=core.replace("confirm('End this task? Unclaimed tasks may be removed.')","confirm('Remove this task from the current task list? Existing claim history will be preserved.')");
write('assets/js/admin/core.js',core);

// Desktop task workspace polish.
let css=read('assets/css/product-experience.css');
css += `\n\n/* 2026-08-09 desktop task and Admin workspace refinement */\n@media(min-width:1000px){\n #view-tasks>.container,#view-visits>.container{max-width:1320px}\n #view-tasks .activity-guide,#view-visits .activity-guide{display:grid;grid-template-columns:minmax(260px,.72fr) minmax(0,1.28fr);align-items:center;gap:22px;padding:24px 28px;border-radius:24px}\n #view-tasks .activity-guide-grid,#view-visits .activity-guide-grid{margin:0;grid-template-columns:repeat(3,minmax(0,1fr))}\n #task-list,#visit-list{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n #task-list .list-card,#visit-list .list-card{min-height:250px;padding:20px;border-radius:22px;display:flex;flex-direction:column;box-shadow:0 14px 34px rgba(28,65,119,.08)}\n #task-list .list-card:hover,#visit-list .list-card:hover{transform:translateY(-3px);box-shadow:0 20px 44px rgba(28,65,119,.13)}\n #task-list .list-card .primary,#visit-list .list-card .primary{margin-top:auto}\n #view-admin .admin-task-layout{grid-template-columns:minmax(0,1.55fr) minmax(360px,.65fr);gap:26px}\n #view-admin .admin-task-layout>.card{padding:26px;border-radius:24px}\n #view-admin #task-form>.quick-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 16px}\n #view-admin #task-admin-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}\n #view-admin #task-admin-list .list-card{height:100%;display:flex;flex-direction:column}\n #view-admin #task-admin-list .quick-grid{margin-top:auto;grid-template-columns:repeat(3,minmax(0,1fr))}\n #view-admin .task-preview-panel{border:1px solid #d9e6f3;background:linear-gradient(180deg,#fff,#f6faff);box-shadow:0 18px 45px rgba(28,65,119,.10)}\n}\n@media(min-width:1500px){#task-list,#visit-list{grid-template-columns:repeat(3,minmax(0,1fr))}#view-admin #task-admin-list{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(min-width:1000px) and (max-width:1180px){#task-list,#visit-list{grid-template-columns:repeat(2,minmax(0,1fr))}#view-admin #task-form>.quick-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}\n`;
write('assets/css/product-experience.css',css);

// Cache-bust the changed production assets.
let html=read('index.html');
html=html.replaceAll('20260805-experience-r1','20260809-controls-r1');
write('index.html',html);

for(const path of['scripts/validate-final-completion.mjs','scripts/validate-product-experience.mjs']){
 let src=read(path);src=src.replaceAll('20260805-experience-r1','20260809-controls-r1');write(path,src);
}

let runOrder=read('supabase/PRODUCTION_RUN_ORDER.md');
if(!runOrder.includes('earnchat_chat_timing_controls_20260809.sql')){
 runOrder=runOrder.replace('9. `earnchat_admin_runtime_unification_20260802.sql`\n10. `earnchat_configuration_control_verify_20260801.sql`','9. `earnchat_admin_runtime_unification_20260802.sql`\n10. `earnchat_chat_timing_controls_20260809.sql`\n11. `earnchat_configuration_control_verify_20260801.sql`');
 runOrder=runOrder.replace('11. `earnchat_production_verify.sql`','12. `earnchat_production_verify.sql`');
}
write('supabase/PRODUCTION_RUN_ORDER.md',runOrder);

console.log('Applied desktop tasks, task removal, flexible chat timing and countdown repair.');
